-- world_map_data.lua contains bundled reference data. See its schema below and CODE_GUIDE.md.
-- Used by: main.lua, world_map_icons.lua.
--[=[
BEGINNER WALKTHROUGH: world_map_data.lua

Each outer block is ONE surface map pin. This is an ordered list; its array index matters.
x/z are map-world tile coordinates; category is a native key/filter ID; sprite is native
foreground artwork; optional background is native backing artwork; tooltip is display text
possibly containing <br>. Optional record supplies typed detail rather than a plain label.

Example reuse:
  local pins = require('world_map_data')
  for index, pin in ipairs(pins) do print(index, pin.x, pin.z, pin.category) end
  local target = require('dungeon_links')[1312] -- same index as the Scabarite surface pin
  if target ~= nil then print(require('map_areas').Get(target).name) end
world_map_icons.lua draws these and retains their indices for hover/click lookup.
Those indices are FOREIGN KEYS into pin_details, navigation_details, dungeon_details and
dungeon_links. Never sort this data in place without rebuilding all linked tables.
The renderer instead sorts a separate list of index+record pairs.

Cross-file connections:
  No require dependencies inside this file.
  Required directly by: main.lua, world_map_icons.lua.

require normally caches a module after the first load. A data module returns values;
a helper module returns functions/state constructors. See CODE_GUIDE.md for the full flow.
]=]

--[[
Bundled surface markers exported from local native map/scenery cache data.
Schema: ordered array of {x, z, category, sprite, background?, tooltip, record?}.
x/z are transformed surface-map tiles; sprite/background are native sprite IDs.
IMPORTANT: array positions are stable foreign keys used by pin_details, dungeon_details,
dungeon_links and navigation_details. Reordering requires rebuilding those linked tables.
These are cached reference markers; conditional native markers may differ in live state.
]]

-- Native map data; unclassified Other markers excluded.
